import java.time.Duration;
import java.time.LocalDate;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;
import tools.jackson.databind.json.JsonMapper;

@Service
public class AvailabilityService {
    private static final Logger log = LoggerFactory.getLogger(AvailabilityService.class);
    private static final Duration TTL = Duration.ofSeconds(60);

    private final StringRedisTemplate redis;
    private final JsonMapper json;
    private final AvailabilityRepository repository;

    public AvailabilityService(StringRedisTemplate redis, JsonMapper json, AvailabilityRepository repository) {
        this.redis = redis;
        this.json = json;
        this.repository = repository;
    }

    static String key(long roomId, LocalDate date) {
        return "roombook:availability:%d:%s".formatted(roomId, date);
    }

    public Availability get(long roomId, LocalDate date) {
        String key = key(roomId, date);
        String cached = null;
        try {
            cached = redis.opsForValue().get(key);
        } catch (DataAccessException e) {
            log.warn("cache read failed for {}", key, e);
        }
        if (cached != null) {
            return json.readValue(cached, Availability.class);
        }

        Availability fresh = repository.compute(roomId, date);
        try {
            redis.opsForValue().set(key, json.writeValueAsString(fresh), TTL);
        } catch (DataAccessException e) {
            log.warn("cache write failed for {}", key, e);
        }
        return fresh;
    }

    public void evict(long roomId, LocalDate date) {
        redis.delete(key(roomId, date));
    }
}

