import dev.hackuniversity.roombook.rooms.AvailabilityService;
import java.time.LocalDate;
import java.time.ZoneId;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

@Component
class BookingCacheListener {
    // Both Roombook buildings are in New York.
    private static final ZoneId CAMPUS = ZoneId.of("America/New_York");

    private final AvailabilityService availability;

    BookingCacheListener(AvailabilityService availability) {
        this.availability = availability;
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    void onConfirmed(BookingConfirmed event) {
        availability.evict(event.roomId(), LocalDate.ofInstant(event.startsAt(), CAMPUS));
    }
}

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URI;
import java.time.Instant;
import java.util.List;
import org.slf4j.MDC;
import org.springframework.core.annotation.Order;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.RedisScript;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import tools.jackson.databind.json.JsonMapper;

@Component
@Order(-101)
public class LoginRateLimitFilter extends OncePerRequestFilter {
    private static final long LIMIT = 10;
    private static final long WINDOW_SECONDS = 15 * 60;
    private static final RedisScript<Long> FIXED_WINDOW = RedisScript.of("""
            local count = redis.call('INCR', KEYS[1])
            if count == 1 then
              redis.call('EXPIRE', KEYS[1], ARGV[1])
            end
            return count
            """, Long.class);

    private final StringRedisTemplate redis;
    private final JsonMapper json;

    public LoginRateLimitFilter(StringRedisTemplate redis, JsonMapper json) {
        this.redis = redis;
        this.json = json;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !request.getRequestURI().equals("/v1/auth/login");
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        long now = Instant.now().getEpochSecond();
        long windowStart = now - now % WINDOW_SECONDS;
        String key = "roombook:rl:login:%s:%d".formatted(request.getRemoteAddr(), windowStart);

        Long count = redis.execute(FIXED_WINDOW, List.of(key), String.valueOf(WINDOW_SECONDS));
        if (count != null && count > LIMIT) {
            ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.TOO_MANY_REQUESTS,
                    "Too many login attempts. Try again later.");
            problem.setType(URI.create("https://roombook.example/problems/rate-limited"));
            problem.setTitle("Too many requests");
            problem.setInstance(URI.create(request.getRequestURI()));
            problem.setProperty("requestId", MDC.get("requestId"));
            response.setStatus(429);
            response.setHeader("Retry-After", String.valueOf(windowStart + WINDOW_SECONDS - now));
            response.setContentType("application/problem+json");
            json.writeValue(response.getOutputStream(), problem);
            return;
        }
        chain.doFilter(request, response);
    }
}

import java.time.Duration;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.annotation.Profile;
import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.connection.stream.Consumer;
import org.springframework.data.redis.connection.stream.MapRecord;
import org.springframework.data.redis.connection.stream.ReadOffset;
import org.springframework.data.redis.connection.stream.StreamOffset;
import org.springframework.data.redis.connection.stream.StreamReadOptions;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
@Profile("worker")
class EmailWorker {
    private static final Logger log = LoggerFactory.getLogger(EmailWorker.class);

    private final StringRedisTemplate redis;
    private final ConfirmationEmails emails;
    private final Consumer consumer = Consumer.from(EmailJobs.GROUP, "worker-" + ProcessHandle.current().pid());

    EmailWorker(StringRedisTemplate redis, ConfirmationEmails emails) {
        this.redis = redis;
        this.emails = emails;
        try {
            redis.opsForStream().createGroup(EmailJobs.STREAM, ReadOffset.from("0"), EmailJobs.GROUP);
        } catch (DataAccessException e) {
            log.debug("group already exists");
        }
    }

    @Scheduled(fixedDelay = 100)
    void poll() {
        List<MapRecord<String, Object, Object>> records = redis.opsForStream().read(consumer,
                StreamReadOptions.empty().count(10).block(Duration.ofSeconds(5)),
                StreamOffset.create(EmailJobs.STREAM, ReadOffset.lastConsumed()));
        for (MapRecord<String, Object, Object> record : records == null ? List.<MapRecord<String, Object, Object>>of() : records) {
            try {
                emails.send(Long.parseLong((String) record.getValue().get("bookingId")));
                redis.opsForStream().acknowledge(EmailJobs.GROUP, record);
            } catch (RuntimeException e) {
                log.error("job {} failed, it stays pending", record.getId(), e);
            }
        }
    }
}

import java.io.IOException;
import java.time.Duration;
import org.springframework.data.redis.connection.MessageListener;
import org.springframework.data.redis.listener.ChannelTopic;
import org.springframework.data.redis.listener.RedisMessageListenerContainer;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

@RestController
@RequestMapping("/v1/rooms")
class RoomEventsController {
    private final RedisMessageListenerContainer listeners;
    private final JsonMapper json;

    RoomEventsController(RedisMessageListenerContainer listeners, JsonMapper json) {
        this.listeners = listeners;
        this.json = json;
    }

    static ChannelTopic channel(long roomId) {
        return new ChannelTopic("roombook:rooms:" + roomId + ":events");
    }

    @GetMapping(path = "/{roomId}/events", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    SseEmitter events(@PathVariable long roomId) throws IOException {
        SseEmitter emitter = new SseEmitter(Duration.ofMinutes(30).toMillis());
        emitter.send(SseEmitter.event().reconnectTime(5000));

        MessageListener listener = (message, pattern) -> {
            JsonNode event = json.readTree(message.getBody());
            try {
                emitter.send(SseEmitter.event()
                        .id(event.get("id").asString())
                        .name("availability")
                        .data(event.get("data").toString()));
            } catch (IOException e) {
                emitter.completeWithError(e);
            }
        };
        ChannelTopic topic = channel(roomId);
        listeners.addMessageListener(listener, topic);
        emitter.onCompletion(() -> listeners.removeMessageListener(listener, topic));
        return emitter;
    }
}
